#include<bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1e9+7;
const int SIZE = 1<<20; // 1048576

int64 power(int64 base, int64 exp) {
    int64 res = 1;
    while (exp) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return res;
}
int64 modInv(int64 x) {
    return power(x, MOD-2);
}

void addMod(int &x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
}
void subMod(int &x, int y) {
    x -= y;
    if (x < 0) x += MOD;
}

void fwt(int *a, int opt) {
    int n = 1<<20;
    for (int len = 2; len <= n; len <<= 1) {
        int half = len >> 1;
        for (int i = 0; i < n; i += len) {
            for (int j = i; j < i + half; ++j) {
                if (opt == 1) addMod(a[j], a[j+half]);
                else subMod(a[j], a[j+half]);
            }
        }
    }
}

int main() {
    int n;
    scanf("%d", &n);
    vector<vector<int64>> p(10, vector<int64>(10, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            scanf("%d", &p[i][j]);
            p[i][j] = (int64)p[i][j] * modInv(100) % MOD;
        }
    }
    if (n < 6) {
        for (int i = n; i < 6; ++i) p[i][i] = 1;
        n = 6;
    }
    int fullMask = (1<<6) - 1; // 63
    int id[64], cnt = 0;
    for (int i = 0; i < 64; ++i) {
        if (__builtin_popcount(i) == 3) id[i] = cnt++;
    }
    vector<int> X(SIZE, 0), Y(SIZE, 0);
    // Process rows 0..2
    for (int i = 0; i < (1<<18); ++i) {
        int m1 = i & fullMask;
        int m2 = (i >> 6) & fullMask;
        int m3 = (i >> 12) & fullMask;
        int mask = 0;
        int64 prob = 1;
        for (int j = 0; j < 6; ++j) {
            if (m1 >> j & 1) prob = prob * p[0][j] % MOD;
            else prob = prob * (MOD + 1 - p[0][j]) % MOD;
        }
        for (int j = 0; j < 6; ++j) {
            if (m2 >> j & 1) prob = prob * p[1][j] % MOD;
            else prob = prob * (MOD + 1 - p[1][j]) % MOD;
        }
        for (int j = 0; j < 6; ++j) {
            if (m3 >> j & 1) prob = prob * p[2][j] % MOD;
            else prob = prob * (MOD + 1 - p[2][j]) % MOD;
        }
        // (omitting the always-true condition from original)
        for (int a = 0; a < 6; ++a) {
            if (((m1 >> a) & 1) == 0) continue;
            for (int b = 0; b < 6; ++b) {
                if (a == b || ((m2 >> b) & 1) == 0) continue;
                for (int c = 0; c < 6; ++c) {
                    if (a == c || b == c || ((m3 >> c) & 1) == 0) continue;
                    int triple = (1<<a) | (1<<b) | (1<<c);
                    mask |= 1 << id[triple];
                }
            }
        }
        addMod(X[mask], prob);
    }
    // Process rows 3..5
    for (int i = 0; i < (1<<18); ++i) {
        int m1 = i & fullMask;
        int m2 = (i >> 6) & fullMask;
        int m3 = (i >> 12) & fullMask;
        int mask = 0;
        int64 prob = 1;
        for (int j = 0; j < 6; ++j) {
            if (m1 >> j & 1) prob = prob * p[3][j] % MOD;
            else prob = prob * (MOD + 1 - p[3][j]) % MOD;
        }
        for (int j = 0; j < 6; ++j) {
            if (m2 >> j & 1) prob = prob * p[4][j] % MOD;
            else prob = prob * (MOD + 1 - p[4][j]) % MOD;
        }
        for (int j = 0; j < 6; ++j) {
            if (m3 >> j & 1) prob = prob * p[5][j] % MOD;
            else prob = prob * (MOD + 1 - p[5][j]) % MOD;
        }
        for (int a = 0; a < 6; ++a) {
            if (((m1 >> a) & 1) == 0) continue;
            for (int b = 0; b < 6; ++b) {
                if (a == b || ((m2 >> b) & 1) == 0) continue;
                for (int c = 0; c < 6; ++c) {
                    if (a == c || b == c || ((m3 >> c) & 1) == 0) continue;
                    int triple = (1<<a) | (1<<b) | (1<<c);
                    triple ^= fullMask;
                    mask |= 1 << id[triple];
                }
            }
        }
        addMod(Y[mask], prob);
    }
    fwt(X.data(), 1);
    fwt(Y.data(), 1);
    for (int i = 0; i < SIZE; ++i) {
        X[i] = (int64)X[i] * Y[i] % MOD;
    }
    fwt(X.data(), -1);
    int ans = 0;
    for (int i = 1; i < SIZE; ++i) addMod(ans, X[i]);
    printf("%d\n", ans);
    return 0;
}
